def allocate_cents(total, weights):
    if isinstance(total, bool) or not isinstance(total, int):
        raise TypeError("total must be an integer")
    if total < 0:
        raise ValueError("total must be nonnegative")
    if not isinstance(weights, list):
        raise TypeError("weights must be a list")
    if not weights:
        raise ValueError("weights must not be empty")
    for weight in weights:
        if isinstance(weight, bool) or not isinstance(weight, int):
            raise TypeError("weights must contain integers")
        if weight <= 0:
            raise ValueError("weights must be positive")
    weight_sum = sum(weights)
    numerators = [total * weight for weight in weights]
    allocations = [numerator // weight_sum for numerator in numerators]
    remaining = total - sum(allocations)
    order = sorted(range(len(weights)), key=lambda index: (-numerators[index] % weight_sum, index))
    for index in order[:remaining]:
        allocations[index] += 1
    return allocations

import math

def categorical_loss_grad(logits, labels):
    if not isinstance(logits, list) or not logits:
        raise ValueError("logits must be a nonempty list")
    if not isinstance(labels, list) or len(labels) != len(logits):
        raise ValueError("labels must match logits")
    class_count = None
    for row in logits:
        if not isinstance(row, list) or not row:
            raise ValueError("logits must contain nonempty rows")
        if class_count is None:
            class_count = len(row)
        elif len(row) != class_count:
            raise ValueError("logits must be rectangular")
        if class_count < 2:
            raise ValueError("at least two classes are required")
        for value in row:
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError("logits must be numeric")
            if not math.isfinite(value):
                raise ValueError("logits must be finite")
    for label in labels:
        if isinstance(label, bool) or not isinstance(label, int):
            raise ValueError("labels must be integer class indices")
        if label < 0 or label >= class_count:
            raise ValueError("label is out of range")
    count = len(logits)
    loss = 0.0
    gradient = []
    for row, label in zip(logits, labels):
        maximum = max(row)
        exponentials = [math.exp(value - maximum) for value in row]
        total = sum(exponentials)
        probabilities = [value / total for value in exponentials]
        loss += maximum + math.log(total) - row[label]
        gradient.append([(probability - (index == label)) / count for index, probability in enumerate(probabilities)])
    return loss / count, gradient

def check_contract(fn):
    assert fn(1) == 1
    assert fn(32768) == 32768
    assert fn(65535) == 65535

    def expect(exception_type, value):
        try:
            fn(value)
        except exception_type:
            return
        except Exception as error:
            raise AssertionError("wrong exception type") from error
        raise AssertionError("expected an exception")

    for value in (0, -1, 65536, 10**100):
        expect(ValueError, value)
    for value in (True, False, 1.0, "80", None, [], {}, object()):
        expect(TypeError, value)
